-- ============================================================================
-- 0028_magic_items_tokens_part2of2.sql
--
-- Full SRD 5.1 magic items (237, CC-BY-4.0) as 'item' tokens with full
-- details + first-letter monogram placeholder art (/icons/items/_mono/<L>.svg).
-- Run both parts, any order. Idempotent: skips an item you already have by name.
-- Attribution: D&D 5.1 SRD, CC-BY-4.0 (see details.source).
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, details)
  select me, v.name, v.image_url, 'item', 'medium',
         jsonb_build_object('kind','item','item', v.item::jsonb)
  from (values
    ('Oil of Etherealness', '/icons/items/_mono/O.svg', '{"name":"Oil of Etherealness","itemType":"Potion","rarity":"rare","description":"Beads of this cloudy gray oil form on the outside of its container and quickly evaporate. The oil can cover a Medium or smaller creature, along with the equipment it''s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the _etherealness_ spell for 1 hour.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Oil of Sharpness', '/icons/items/_mono/O.svg', '{"name":"Oil of Sharpness","itemType":"Potion","rarity":"very rare","description":"This clear, gelatinous oil sparkles with tiny, ultrathin silver shards. The oil can coat one slashing or piercing weapon or up to 5 pieces of slashing or piercing ammunition. Applying the oil takes 1 minute. For 1 hour, the coated item is magical and has a +3 bonus to attack and damage rolls.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Oil of Slipperiness', '/icons/items/_mono/O.svg', '{"name":"Oil of Slipperiness","itemType":"Potion","rarity":"uncommon","description":"This sticky black unguent is thick and heavy in the container, but it flows quickly when poured. The oil can cover a Medium or smaller creature, along with the equipment it''s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of a _freedom of movement_ spell for 8 hours.\n\nAlternatively, the oil can be poured on the ground as an action, where it covers a 10-foot square, duplicating the effect of the _grease_ spell in that area for 8 hours.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Orb of Dragonkind', '/icons/items/_mono/O.svg', '{"name":"Orb of Dragonkind","itemType":"Wondrous item","rarity":"artifact","description":"Ages past, elves and humans waged a terrible war against evil dragons. When the world seemed doomed, powerful wizards came together and worked their greatest magic, forging five _Orbs of Dragonkind_ (or _Dragon Orbs_) to help them defeat the dragons. One orb was taken to each of the five wizard towers, and there they were used to speed the war toward a victorious end. The wizards used the orbs to lure dragons to them, then destroyed the dragons with powerful magic.\n\nAs the wizard towers fell in later ages, the orbs were destroyed or faded into legend, and only three are thought to survive. Their magic has been warped and twisted over the centuries, so although their primary purpose of calling dragons still functions, they also allow some measure of control over dragons.\n\nEach orb contains the essence of an evil dragon, a presence that resents any attempt to coax magic from it. Those lacking in force of personality might find themselves enslaved to an orb.\n\nAn orb is an etched crystal globe about 10 inches in diameter. When used, it grows to about 20 inches in diameter, and mist swirls inside it.\n\nWhile attuned to an orb, you can use an action to peer into the orb''s depths and speak its command word. You must then make a DC 15 Charisma check. On a successful check, you control the orb for as long as you remain attuned to it. On a failed check, you become charmed by the orb for as long as you remain attuned to it.\n\nWhile you are charmed by the orb, you can''t voluntarily end your attunement to it, and the orb casts _suggestion_ on you at will (save DC 18), urging you to work toward the evil ends it desires. The dragon essence within the orb might want many things: the annihilation of a particular people, freedom from the orb, to spread suffering in the world, to advance the worship of Tiamat, or something else the GM decides.\n\n**_Random Properties_**. An _Orb of Dragonkind_ has the following random properties:\n\n* 2 minor beneficial properties\n* 1 minor detrimental property\n* 1 major detrimental property\n\n**_Spells_**. The orb has 7 charges and regains 1d4 + 3 expended charges daily at dawn. If you control the orb, you can use an action and expend 1 or more charges to cast one of the following spells (save DC 18) from it: _cure wounds_ (5th-level version, 3 charges), _daylight_ (1 charge), _death ward_ (2 charges), or _scrying_ (3 charges).\n\nYou can also use an action to cast the _detect magic_ spell from the orb without using any charges.\n\n**_Call Dragons_**. While you control the orb, you can use an action to cause the artifact to issue a telepathic call that extends in all directions for 40 miles. Evil dragons in range feel compelled to come to the orb as soon as possible by the most direct route. Dragon deities such as Tiamat are unaffected by this call. Dragons drawn to the orb might be hostile toward you for compelling them against their will. Once you have used this property, it can''t be used again for 1 hour.\n\n**_Destroying an Orb_**. An _Orb of Dragonkind_ appears fragile but is impervious to most damage, including the attacks and breath weapons of dragons. A _disintegrate_ spell or one good hit from a +3 magic weapon is sufficient to destroy an orb, however.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Pearl of Power', '/icons/items/_mono/P.svg', '{"name":"Pearl of Power","itemType":"Wondrous item","rarity":"uncommon","description":"While this pearl is on your person, you can use an action to speak its command word and regain one expended spell slot. If the expended slot was of 4th level or higher, the new slot is 3rd level. Once you use the pearl, it can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Periapt of Health', '/icons/items/_mono/P.svg', '{"name":"Periapt of Health","itemType":"Wondrous item","rarity":"uncommon","description":"You are immune to contracting any disease while you wear this pendant. If you are already infected with a disease, the effects of the disease are suppressed you while you wear the pendant.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Periapt of Proof against Poison', '/icons/items/_mono/P.svg', '{"name":"Periapt of Proof against Poison","itemType":"Wondrous item","rarity":"rare","description":"This delicate silver chain has a brilliant-cut black gem pendant. While you wear it, poisons have no effect on you. You are immune to the poisoned condition and have immunity to poison damage.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Periapt of Wound Closure', '/icons/items/_mono/P.svg', '{"name":"Periapt of Wound Closure","itemType":"Wondrous item","rarity":"uncommon","description":"While you wear this pendant, you stabilize whenever you are dying at the start of your turn. In addition, whenever you roll a Hit Die to regain hit points, double the number of hit points it restores.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Philter of Love', '/icons/items/_mono/P.svg', '{"name":"Philter of Love","itemType":"Potion","rarity":"uncommon","description":"The next time you see a creature within 10 minutes after drinking this philter, you become charmed by that creature for 1 hour. If the creature is of a species and gender you are normally attracted to, you regard it as your true love while you are charmed. This potion''s rose-hued, effervescent liquid contains one easy-to-miss bubble shaped like a heart.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Pipes of Haunting', '/icons/items/_mono/P.svg', '{"name":"Pipes of Haunting","itemType":"Wondrous item","rarity":"uncommon","description":"You must be proficient with wind instruments to use these pipes. They have 3 charges. You can use an action to play them and expend 1 charge to create an eerie, spellbinding tune. Each creature within 30 feet of you that hears you play must succeed on a DC 15 Wisdom saving throw or become frightened of you for 1 minute. If you wish, all creatures in the area that aren''t hostile toward you automatically succeed on the saving throw. A creature that fails the saving throw can repeat it at the end of each of its turns, ending the effect on itself on a success. A creature that succeeds on its saving throw is immune to the effect of these pipes for 24 hours. The pipes regain 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Pipes of the Sewers', '/icons/items/_mono/P.svg', '{"name":"Pipes of the Sewers","itemType":"Wondrous item","rarity":"uncommon","description":"You must be proficient with wind instruments to use these pipes. While you are attuned to the pipes, ordinary rats and giant rats are indifferent toward you and will not attack you unless you threaten or harm them.\n\nThe pipes have 3 charges. If you play the pipes as an action, you can use a bonus action to expend 1 to 3 charges, calling forth one swarm of rats with each expended charge, provided that enough rats are within half a mile of you to be called in this fashion (as determined by the GM). If there aren''t enough rats to form a swarm, the charge is wasted. Called swarms move toward the music by the shortest available route but aren''t under your control otherwise. The pipes regain 1d3 expended charges daily at dawn.\n\nWhenever a swarm of rats that isn''t under another creature''s control comes within 30 feet of you while you are playing the pipes, you can make a Charisma check contested by the swarm''s Wisdom check. If you lose the contest, the swarm behaves as it normally would and can''t be swayed by the pipes'' music for the next 24 hours. If you win the contest, the swarm is swayed by the pipes'' music and becomes friendly to you and your companions for as long as you continue to play the pipes each round as an action. A friendly swarm obeys your commands. If you issue no commands to a friendly swarm, it defends itself but otherwise takes no actions. If a friendly swarm starts its turn and can''t hear the pipes'' music, your control over that swarm ends, and the swarm behaves as it normally would and can''t be swayed by the pipes'' music for the next 24 hours.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Plate Armor of Etherealness', '/icons/items/_mono/P.svg', '{"name":"Plate Armor of Etherealness","itemType":"Armor","rarity":"legendary","description":"While you''re wearing this armor, you can speak its command word as an action to gain the effect of the _etherealness_ spell, which last for 10 minutes or until you remove the armor or use an action to speak the command word again. This property of the armor can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","baseType":"plate","attunement":true}'),
    ('Portable Hole', '/icons/items/_mono/P.svg', '{"name":"Portable Hole","itemType":"Wondrous item","rarity":"rare","description":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter.\n\nYou can use an action to unfold a _portable hole_ and place it on or against a solid surface, whereupon the _portable hole_ creates an extradimensional hole 10 feet deep. The cylindrical space within the hole exists on a different plane, so it can''t be used to create open passages. Any creature inside an open _portable hole_ can exit the hole by climbing out of it.\n\nYou can use an action to close a _portable hole_ by taking hold of the edges of the cloth and folding it up. Folding the cloth closes the hole, and any creatures or objects within remain in the extradimensional space. No matter what''s in it, the hole weighs next to nothing.\n\nIf the hole is folded up, a creature within the hole''s extradimensional space can use an action to make a DC 10 Strength check. On a successful check, the creature forces its way out and appears within 5 feet of the _portable hole_ or the creature carrying it. A breathing creature within a closed _portable hole_ can survive for up to 10 minutes, after which time it begins to suffocate.\n\nPlacing a _portable hole_ inside an extradimensional space created by a _bag of holding_, _handy haversack_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can''t be reopened.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Animal Friendship', '/icons/items/_mono/P.svg', '{"name":"Potion of Animal Friendship","itemType":"Potion","rarity":"uncommon","description":"When you drink this potion, you can cast the _animal friendship_ spell (save DC 13) for 1 hour at will. Agitating this muddy liquid brings little bits into view: a fish scale, a hummingbird tongue, a cat claw, or a squirrel hair.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Clairvoyance', '/icons/items/_mono/P.svg', '{"name":"Potion of Clairvoyance","itemType":"Potion","rarity":"rare","description":"When you drink this potion, you gain the effect of the _clairvoyance_ spell. An eyeball bobs in this yellowish liquid but vanishes when the potion is opened.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Climbing', '/icons/items/_mono/P.svg', '{"name":"Potion of Climbing","itemType":"Potion","rarity":"common","description":"When you drink this potion, you gain a climbing speed equal to your walking speed for 1 hour. During this time, you have advantage on Strength (Athletics) checks you make to climb. The potion is separated into brown, silver, and gray layers resembling bands of stone. Shaking the bottle fails to mix the colors.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Diminution', '/icons/items/_mono/P.svg', '{"name":"Potion of Diminution","itemType":"Potion","rarity":"rare","description":"When you drink this potion, you gain the \"reduce\" effect of the _enlarge/reduce_ spell for 1d4 hours (no concentration required). The red in the potion''s liquid continuously contracts to a tiny bead and then expands to color the clear liquid around it. Shaking the bottle fails to interrupt this process.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Flying', '/icons/items/_mono/P.svg', '{"name":"Potion of Flying","itemType":"Potion","rarity":"very rare","description":"When you drink this potion, you gain a flying speed equal to your walking speed for 1 hour and can hover. If you''re in the air when the potion wears off, you fall unless you have some other means of staying aloft. This potion''s clear liquid floats at the top of its container and has cloudy white impurities drifting in it.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Gaseous Form', '/icons/items/_mono/P.svg', '{"name":"Potion of Gaseous Form","itemType":"Potion","rarity":"rare","description":"When you drink this potion, you gain the effect of the _gaseous form_ spell for 1 hour (no concentration required) or until you end the effect as a bonus action. This potion''s container seems to hold fog that moves and pours like water.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Giant Strength', '/icons/items/_mono/P.svg', '{"name":"Potion of Giant Strength","itemType":"Potion","rarity":"rare","description":"When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score.\n\nThis potion''s transparent liquid has floating in it a sliver of fingernail from a giant of the appropriate type. The _potion of frost giant strength_ and the _potion of stone giant strength_ have the same effect.\n\n| Type of Giant     | Strength | Rarity    |\n|-------------------|----------|-----------|\n| Hill giant        | 21       | Uncommon  |\n| Frost/stone giant | 23       | Rare      |\n| Fire giant        | 25       | Rare      |\n| Cloud giant       | 27       | Very rare |\n| Storm giant       | 29       | Legendary |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Growth', '/icons/items/_mono/P.svg', '{"name":"Potion of Growth","itemType":"Potion","rarity":"uncommon","description":"When you drink this potion, you gain the \"enlarge\" effect of the _enlarge/reduce_ spell for 1d4 hours (no concentration required). The red in the potion''s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts. Shaking the bottle fails to interrupt this process.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Healing', '/icons/items/_mono/P.svg', '{"name":"Potion of Healing","itemType":"Potion","rarity":"rare","description":"You regain hit points when you drink this potion. The number of hit points depends on the potion''s rarity, as shown in the Potions of Healing table. Whatever its potency, the potion''s red liquid glimmers when agitated.\n\n**Potions of Healing (table)**\n\n| Potion of ...    | Rarity    | HP Regained |\n|------------------|-----------|-------------|\n| Healing          | Common    | 2d4 + 2     |\n| Greater healing  | Uncommon  | 4d4 + 4     |\n| Superior healing | Rare      | 8d4 + 8     |\n| Supreme healing  | Very rare | 10d4 + 20   |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Heroism', '/icons/items/_mono/P.svg', '{"name":"Potion of Heroism","itemType":"Potion","rarity":"rare","description":"For 1 hour after drinking it, you gain 10 temporary hit points that last for 1 hour. For the same duration, you are under the effect of the _bless_ spell (no concentration required). This blue potion bubbles and steams as if boiling.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Invisibility', '/icons/items/_mono/P.svg', '{"name":"Potion of Invisibility","itemType":"Potion","rarity":"very rare","description":"This potion''s container looks empty but feels as though it holds liquid. When you drink it, you become invisible for 1 hour. Anything you wear or carry is invisible with you. The effect ends early if you attack or cast a spell.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Mind Reading', '/icons/items/_mono/P.svg', '{"name":"Potion of Mind Reading","itemType":"Potion","rarity":"rare","description":"When you drink this potion, you gain the effect of the _detect thoughts_ spell (save DC 13). The potion''s dense, purple liquid has an ovoid cloud of pink floating in it.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Poison', '/icons/items/_mono/P.svg', '{"name":"Potion of Poison","itemType":"Potion","rarity":"uncommon","description":"This concoction looks, smells, and tastes like a _potion of healing_ or other beneficial potion. However, it is actually poison masked by illusion magic. An _identify_ spell reveals its true nature.\n\nIf you drink it, you take 3d6 poison damage, and you must succeed on a DC 13 Constitution saving throw or be poisoned. At the start of each of your turns while you are poisoned in this way, you take 3d6 poison damage. At the end of each of your turns, you can repeat the saving throw. On a successful save, the poison damage you take on your subsequent turns decreases by 1d6. The poison ends when the damage decreases to 0.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Resistance', '/icons/items/_mono/P.svg', '{"name":"Potion of Resistance","itemType":"Potion","rarity":"uncommon","description":"When you drink this potion, you gain resistance to one type of damage for 1 hour. The GM chooses the type or determines it randomly from the options below.\n\n| d10 | Damage Type |\n|-----|-------------|\n| 1   | Acid        |\n| 2   | Cold        |\n| 3   | Fire        |\n| 4   | Force       |\n| 5   | Lightning   |\n| 6   | Necrotic    |\n| 7   | Poison      |\n| 8   | Psychic     |\n| 9   | Radiant     |\n| 10  | Thunder     |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Speed', '/icons/items/_mono/P.svg', '{"name":"Potion of Speed","itemType":"Potion","rarity":"very rare","description":"When you drink this potion, you gain the effect of the _haste_ spell for 1 minute (no concentration required). The potion''s yellow fluid is streaked with black and swirls on its own.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Potion of Water Breathing', '/icons/items/_mono/P.svg', '{"name":"Potion of Water Breathing","itemType":"Potion","rarity":"uncommon","description":"You can breathe underwater for 1 hour after drinking this potion. Its cloudy green fluid smells of the sea and has a jellyfish-like bubble floating in it.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Restorative Ointment', '/icons/items/_mono/R.svg', '{"name":"Restorative Ointment","itemType":"Wondrous item","rarity":"uncommon","description":"This glass jar, 3 inches in diameter, contains 1d4 + 1 doses of a thick mixture that smells faintly of aloe. The jar and its contents weigh 1/2 pound.\n\nAs an action, one dose of the ointment can be swallowed or applied to the skin. The creature that receives it regains 2d8 + 2 hit points, ceases to be poisoned, and is cured of any disease.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Ring of Animal Influence', '/icons/items/_mono/R.svg', '{"name":"Ring of Animal Influence","itemType":"Ring","rarity":"rare","description":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. While wearing the ring, you can use an action to expend 1 of its charges to cast one of the following spells:\n\n* _Animal friendship_ (save DC 13)\n* _Fear_ (save DC 13), targeting only beasts that have an Intelligence of 3 or lower\n* _Speak with animals_","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Ring of Djinni Summoning', '/icons/items/_mono/R.svg', '{"name":"Ring of Djinni Summoning","itemType":"Ring","rarity":"legendary","description":"While wearing this ring, you can speak its command word as an action to summon a particular djinni from the Elemental Plane of Air. The djinni appears in an unoccupied space you choose within 120 feet of you. It remains as long as you concentrate (as if concentrating on a spell), to a maximum of 1 hour, or until it drops to 0 hit points. It then returns to its home plane.\n\nWhile summoned, the djinni is friendly to you and your companions. It obeys any commands you give it, no matter what language you use. If you fail to command it, the djinni defends itself against attackers but takes no other actions.\n\nAfter the djinni departs, it can''t be summoned again for 24 hours, and the ring becomes nonmagical if the djinni dies.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Elemental Command', '/icons/items/_mono/R.svg', '{"name":"Ring of Elemental Command","itemType":"Ring","rarity":"legendary","description":"This ring is linked to one of the four Elemental Planes. The GM chooses or randomly determines the linked plane.\n\nWhile wearing this ring, you have advantage on attack rolls against elementals from the linked plane, and they have disadvantage on attack rolls against you. In addition, you have access to properties based on the linked plane.\n\nThe ring has 5 charges. It regains 1d4 + 1 expended charges daily at dawn. Spells cast from the ring have a save DC of 17.\n\n**_Ring of Air Elemental Command_**. You can expend 2 of the ring''s charges to cast _dominate monster_ on an air elemental. In addition, when you fall, you descend 60 feet per round and take no damage from falling. You can also speak and understand Auran.\n\nIf you help slay an air elemental while attuned to the ring, you gain access to the following additional properties:\n\n* You have resistance to lightning damage.\n* You have a flying speed equal to your walking speed and can hover.\n* You can cast the following spells from the ring, expending the necessary number of charges: _chain lightning_ (3 charges), _gust of wind_ (2 charges), or _wind wall_ (1 charge).\n\n**_Ring of Earth Elemental Command_**. You can expend 2 of the ring''s charges to cast _dominate monster_ on an earth elemental. In addition, you can move in difficult terrain that is composed of rubble, rocks, or dirt as if it were normal terrain. You can also speak and understand Terran.\n\nIf you help slay an earth elemental while attuned to the ring, you gain access to the following additional properties:\n\n* You have resistance to acid damage.\n* You can move through solid earth or rock as if those areas were difficult terrain. If you end your turn there, you are shunted out to the nearest unoccupied space you last occupied.\n* You can cast the following spells from the ring, expending the necessary number of charges: _stone shape_ (2 charges), _stoneskin_ (3 charges), or _wall of stone_ (3 charges).\n\n**_Ring of Fire Elemental Command_**. You can expend 2 of the ring''s charges to cast _dominate monster_ on a fire elemental. In addition, you have resistance to fire damage. You can also speak and understand Ignan.\n\nIf you help slay a fire elemental while attuned to the ring, you gain access to the following additional properties:\n\n* You are immune to fire damage.\n* You can cast the following spells from the ring, expending the necessary number of charges: _burning hands_ (1 charge), _fireball_ (2 charges), and _wall of fire_ (3 charges).\n\n**_Ring of Water Elemental Command_**. You can expend 2 of the ring''s charges to cast _dominate monster_ on a water elemental. In addition, you can stand on and walk across liquid surfaces as if they were solid ground. You can also speak and understand Aquan.\n\nIf you help slay a water elemental while attuned to the ring, you gain access to the following additional properties:\n\n* You can breathe underwater and have a swimming speed equal to your walking speed.\n* You can cast the following spells from the ring, expending the necessary number of charges: _create or destroy water_ (1 charge), _control water_ (3 charges), _ice storm_ (2 charges), or _wall of ice_ (3 charges).","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Evasion', '/icons/items/_mono/R.svg', '{"name":"Ring of Evasion","itemType":"Ring","rarity":"rare","description":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. When you fail a Dexterity saving throw while wearing it, you can use your reaction to expend 1 of its charges to succeed on that saving throw instead.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Feather Falling', '/icons/items/_mono/R.svg', '{"name":"Ring of Feather Falling","itemType":"Ring","rarity":"rare","description":"When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Free Action', '/icons/items/_mono/R.svg', '{"name":"Ring of Free Action","itemType":"Ring","rarity":"rare","description":"While you wear this ring, difficult terrain doesn''t cost you extra movement. In addition, magic can neither reduce your speed nor cause you to be paralyzed or restrained.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Invisibility', '/icons/items/_mono/R.svg', '{"name":"Ring of Invisibility","itemType":"Ring","rarity":"legendary","description":"While wearing this ring, you can turn invisible as an action. Anything you are wearing or carrying is invisible with you. You remain invisible until the ring is removed, until you attack or cast a spell, or until you use a bonus action to become visible again.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Jumping', '/icons/items/_mono/R.svg', '{"name":"Ring of Jumping","itemType":"Ring","rarity":"uncommon","description":"While wearing this ring, you can cast the _jump_ spell from it as a bonus action at will, but can target only yourself when you do so.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Mind Shielding', '/icons/items/_mono/R.svg', '{"name":"Ring of Mind Shielding","itemType":"Ring","rarity":"uncommon","description":"While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type. Creatures can telepathically communicate with you only if you allow it.\n\nYou can use an action to cause the ring to become invisible until you use another action to make it visible, until you remove the ring, or until you die.\n\nIf you die while wearing the ring, your soul enters it, unless it already houses a soul. You can remain in the ring or depart for the afterlife. As long as your soul is in the ring, you can telepathically communicate with any creature wearing it. A wearer can''t prevent this telepathic communication.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Protection', '/icons/items/_mono/R.svg', '{"name":"Ring of Protection","itemType":"Ring","rarity":"rare","description":"You gain a +1 bonus to AC and saving throws while wearing this ring.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Regeneration', '/icons/items/_mono/R.svg', '{"name":"Ring of Regeneration","itemType":"Ring","rarity":"very rare","description":"While wearing this ring, you regain 1d6 hit points every 10 minutes, provided that you have at least 1 hit point. If you lose a body part, the ring causes the missing part to regrow and return to full functionality after 1d6 + 1 days if you have at least 1 hit point the whole time.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Resistance', '/icons/items/_mono/R.svg', '{"name":"Ring of Resistance","itemType":"Ring","rarity":"rare","description":"You have resistance to one damage type while wearing this ring. The gem in the ring indicates the type, which the GM chooses or determines randomly.\n\n| d10 | Damage Type | Gem        |\n|-----|-------------|------------|\n| 1   | Acid        | Pearl      |\n| 2   | Cold        | Tourmaline |\n| 3   | Fire        | Garnet     |\n| 4   | Force       | Sapphire   |\n| 5   | Lightning   | Citrine    |\n| 6   | Necrotic    | Jet        |\n| 7   | Poison      | Amethyst   |\n| 8   | Psychic     | Jade       |\n| 9   | Radiant     | Topaz      |\n| 10  | Thunder     | Spinel     |","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Shooting Stars', '/icons/items/_mono/R.svg', '{"name":"Ring of Shooting Stars","itemType":"Ring","rarity":"very rare","description":"While wearing this ring in dim light or darkness, you can cast _dancing lights_ and _light_ from the ring at will. Casting either spell from the ring requires an action.\n\nThe ring has 6 charges for the following other properties. The ring regains 1d6 expended charges daily at dawn.\n\n**_Faerie Fire_**. You can expend 1 charge as an action to cast _faerie fire_ from the ring.\n\n**_Ball Lightning_**. You can expend 2 charges as an action to create one to four 3-foot-diameter spheres of lightning. The more spheres you create, the less powerful each sphere is individually.\n\nEach sphere appears in an unoccupied space you can see within 120 feet of you. The spheres last as long as you concentrate (as if concentrating on a spell), up to 1 minute. Each sphere sheds dim light in a 30-foot radius.\n\nAs a bonus action, you can move each sphere up to 30 feet, but no farther than 120 feet away from you. When a creature other than you comes within 5 feet of a sphere, the sphere discharges lightning at that creature and disappears. That creature must make a DC 15 Dexterity saving throw. On a failed save, the creature takes lightning damage based on the number of spheres you created.\n\n| Spheres | Lightning Damage |\n|---------|------------------|\n| 4       | 2d4              |\n| 3       | 2d6              |\n| 2       | 5d4              |\n| 1       | 4d12             |\n\n**_Shooting Stars_**. You can expend 1 to 3 charges as an action. For every charge you expend, you launch a glowing mote of light from the ring at a point you can see within 60 feet of you. Each creature within a 15-foot cube originating from that point is showered in sparks and must make a DC 15 Dexterity saving throw, taking 5d4 fire damage on a failed save, or half as much damage on a successful one.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"outdoors at night"}'),
    ('Ring of Spell Storing', '/icons/items/_mono/R.svg', '{"name":"Ring of Spell Storing","itemType":"Ring","rarity":"rare","description":"This ring stores spells cast into it, holding them until the attuned wearer uses them. The ring can store up to 5 levels worth of spells at a time. When found, it contains 1d6 - 1 levels of stored spells chosen by the GM.\n\nAny creature can cast a spell of 1st through 5th level into the ring by touching the ring as the spell is cast. The spell has no effect, other than to be stored in the ring. If the ring can''t hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses.\n\nWhile wearing this ring, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster, but is otherwise treated as if you cast the spell. The spell cast from the ring is no longer stored in it, freeing up space.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Spell Turning', '/icons/items/_mono/R.svg', '{"name":"Ring of Spell Turning","itemType":"Ring","rarity":"legendary","description":"While wearing this ring, you have advantage on saving throws against any spell that targets only you (not in an area of effect). In addition, if you roll a 20 for the save and the spell is 7th level or lower, the spell has no effect on you and instead targets the caster, using the slot level, spell save DC, attack bonus, and spellcasting ability of the caster.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Swimming', '/icons/items/_mono/R.svg', '{"name":"Ring of Swimming","itemType":"Ring","rarity":"uncommon","description":"You have a swimming speed of 40 feet while wearing this ring.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Ring of Telekinesis', '/icons/items/_mono/R.svg', '{"name":"Ring of Telekinesis","itemType":"Ring","rarity":"very rare","description":"While wearing this ring, you can cast the _telekinesis_ spell at will, but you can target only objects that aren''t being worn or carried.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of the Ram', '/icons/items/_mono/R.svg', '{"name":"Ring of the Ram","itemType":"Ring","rarity":"rare","description":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. While wearing the ring, you can use an action to expend 1 to 3 of its charges to attack one creature you can see within 60 feet of you. The ring produces a spectral ram''s head and makes its attack roll with a +7 bonus. On a hit, for each charge you spend, the target takes 2d10 force damage and is pushed 5 feet away from you.\n\nAlternatively, you can expend 1 to 3 of the ring''s charges as an action to try to break an object you can see within 60 feet of you that isn''t being worn or carried. The ring makes a Strength check with a +5 bonus for each charge you spend.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Three Wishes', '/icons/items/_mono/R.svg', '{"name":"Ring of Three Wishes","itemType":"Ring","rarity":"legendary","description":"While wearing this ring, you can use an action to expend 1 of its 3 charges to cast the _wish_ spell from it. The ring becomes nonmagical when you use the last charge.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Ring of Warmth', '/icons/items/_mono/R.svg', '{"name":"Ring of Warmth","itemType":"Ring","rarity":"uncommon","description":"While wearing this ring, you have resistance to cold damage. In addition, you and everything you wear and carry are unharmed by temperatures as low as -50 degrees Fahrenheit.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Ring of Water Walking', '/icons/items/_mono/R.svg', '{"name":"Ring of Water Walking","itemType":"Ring","rarity":"uncommon","description":"While wearing this ring, you can stand on and move across any liquid surface as if it were solid ground.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Ring of X-ray Vision', '/icons/items/_mono/R.svg', '{"name":"Ring of X-ray Vision","itemType":"Ring","rarity":"rare","description":"While wearing this ring, you can use an action to speak its command word. When you do so, you can see into and through solid matter for 1 minute. This vision has a radius of 30 feet. To you, solid objects within that radius appear transparent and don''t prevent light from passing through them. The vision can penetrate 1 foot of stone, 1 inch of common metal, or up to 3 feet of wood or dirt. Thicker substances block the vision, as does a thin sheet of lead.\n\nWhenever you use the ring again before taking a long rest, you must succeed on a DC 15 Constitution saving throw or gain one level of exhaustion.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Robe of Eyes', '/icons/items/_mono/R.svg', '{"name":"Robe of Eyes","itemType":"Wondrous item","rarity":"rare","description":"This robe is adorned with eyelike patterns. While you wear the robe, you gain the following benefits:\n\n* The robe lets you see in all directions, and you have advantage on Wisdom (Perception) checks that rely on sight.\n* You have darkvision out to a range of 120 feet.\n* You can see invisible creatures and objects, as well as see into the Ethereal Plane, out to a range of 120 feet.\n\nThe eyes on the robe can''t be closed or averted. Although you can close or avert your own eyes, you are never considered to be doing so while wearing this robe.\n\nA _light_ spell cast on the robe or a _daylight_ spell cast within 5 feet of the robe causes you to be blinded for 1 minute. At the end of each of your turns, you can make a Constitution saving throw (DC 11 for _light_ or DC 15 for _daylight_), ending the blindness on a success.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Robe of Scintillating Colors', '/icons/items/_mono/R.svg', '{"name":"Robe of Scintillating Colors","itemType":"Wondrous item","rarity":"very rare","description":"This robe has 3 charges, and it regains 1d3 expended charges daily at dawn. While you wear it, you can use an action and expend 1 charge to cause the garment to display a shifting pattern of dazzling hues until the end of your next turn. During this time, the robe sheds bright light in a 30-foot radius and dim light for an additional 30 feet. Creatures that can see you have disadvantage on attack rolls against you. In addition, any creature in the bright light that can see you when the robe''s power is activated must succeed on a DC 15 Wisdom saving throw or become stunned until the effect ends.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Robe of Stars', '/icons/items/_mono/R.svg', '{"name":"Robe of Stars","itemType":"Wondrous item","rarity":"very rare","description":"This black or dark blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saving throws while you wear it.\n\nSix stars, located on the robe''s upper front portion, are particularly large. While wearing this robe, you can use an action to pull off one of the stars and use it to cast _magic missile_ as a 5th-level spell. Daily at dusk, 1d6 removed stars reappear on the robe.\n\nWhile you wear the robe, you can use an action to enter the Astral Plane along with everything you are wearing and carrying. You remain there until you use an action to return to the plane you were on. You reappear in the last space you occupied, or if that space is occupied, the nearest unoccupied space.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Robe of the Archmagi', '/icons/items/_mono/R.svg', '{"name":"Robe of the Archmagi","itemType":"Wondrous item","rarity":"legendary","description":"This elegant garment is made from exquisite cloth of white, gray, or black and adorned with silvery runes. The robe''s color corresponds to the alignment for which the item was created. A white robe was made for good, gray for neutral, and black for evil. You can''t attune to a _robe of the archmagi_ that doesn''t correspond to your alignment.\n\nYou gain these benefits while wearing the robe:\n\n* If you aren''t wearing armor, your base Armor Class is 15 + your Dexterity modifier.\n* You have advantage on saving throws against spells and other magical effects.\n* Your spell save DC and spell attack bonus each increase by 2.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a sorcerer, warlock, or wizard"}'),
    ('Robe of Useful Items', '/icons/items/_mono/R.svg', '{"name":"Robe of Useful Items","itemType":"Wondrous item","rarity":"uncommon","description":"This robe has cloth patches of various shapes and colors covering it. While wearing the robe, you can use an action to detach one of the patches, causing it to become the object or creature it represents. Once the last patch is removed, the robe becomes an ordinary garment.\n\nThe robe has two of each of the following patches:\n\n* Dagger\n* Bullseye lantern (filled and lit)\n* Steel mirror\n* 10-foot pole\n* Hempen rope (50 feet, coiled)\n* Sack\n\nIn addition, the robe has 4d4 other patches. The GM chooses the patches or determines them randomly.\n\n| d100   | Patch                                                                                                                                                                                             |\n|--------|---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n| 01-08  | Bag of 100 gp                                                                                                                                                                                     |\n| 09-15  | Silver coffer (1 foot long, 6 inches wide and deep) worth 500 gp                                                                                                                                  |\n| 16-22  | Iron door (up to 10 feet wide and 10 feet high, barred on one side of your choice), which you can place in an opening you can reach; it conforms to fit the opening, attaching and hinging itself |\n| 23-30  | 10 gems worth 100 gp each                                                                                                                                                                         |\n| 31-44  | Wooden ladder (24 feet long) |\n| 45-51 | A riding horse with saddle bags                                                                                                                                |\n| 52-59  | Pit (a cube 10 feet on a side), which you can place on the ground within 10 feet of you                                                                                                           |\n| 60-68  | 4 potions of healing                                                                                                                                                                              |\n| 69-75  | Rowboat (12 feet long)                                                                                                                                                                            |\n| 76-83  | Spell scroll containing one spell of 1st to 3rd level                                                                                                                                             |\n| 84-90  | 2 mastiffs                                                                                                                                                                                        |\n| 91-96  | Window (2 feet by 4 feet, up to 2 feet deep), which you can place on a vertical surface you can reach                                                                                             |\n| 97-100 | Portable ram                                                                                                                                                                                      |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Rod of Absorption', '/icons/items/_mono/R.svg', '{"name":"Rod of Absorption","itemType":"Rod","rarity":"very rare","description":"While holding this rod, you can use your reaction to absorb a spell that is targeting only you and not with an area of effect. The absorbed spell''s effect is canceled, and the spell''s energy-not the spell itself-is stored in the rod. The energy has the same level as the spell when it was cast. The rod can absorb and store up to 50 levels of energy over the course of its existence. Once the rod absorbs 50 levels of energy, it can''t absorb more. If you are targeted by a spell that the rod can''t store, the rod has no effect on that spell.\n\nWhen you become attuned to the rod, you know how many levels of energy the rod has absorbed over the course of its existence, and how many levels of spell energy it currently has stored.\n\nIf you are a spellcaster holding the rod, you can convert energy stored in it into spell slots to cast spells you have prepared or know. You can create spell slots only of a level equal to or lower than your own spell slots, up to a maximum of 5th level. You use the stored levels in place of your slots, but otherwise cast the spell as normal. For example, you can use 3 levels stored in the rod as a 3rd-level spell slot.\n\nA newly found rod has 1d10 levels of spell energy stored in it already. A rod that can no longer absorb spell energy and has no energy remaining becomes nonmagical.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Rod of Alertness', '/icons/items/_mono/R.svg', '{"name":"Rod of Alertness","itemType":"Rod","rarity":"very rare","description":"This rod has a flanged head and the following properties.\n\n**_Alertness_**. While holding the rod, you have advantage on Wisdom (Perception) checks and on rolls for initiative.\n\n**_Spells_**. While holding the rod, you can use an action to cast one of the following spells from it: _detect evil and good_, _detect magic_, _detect poison and disease_, or _see invisibility._\n\n**_Protective Aura_**. As an action, you can plant the haft end of the rod in the ground, whereupon the rod''s head sheds bright light in a 60-foot radius and dim light for an additional 60 feet. While in that bright light, you and any creature that is friendly to you gain a +1 bonus to AC and saving throws and can sense the location of any invisible hostile creature that is also in the bright light.\n\nThe rod''s head stops glowing and the effect ends after 10 minutes, or when a creature uses an action to pull the rod from the ground. This property can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Rod of Lordly Might', '/icons/items/_mono/R.svg', '{"name":"Rod of Lordly Might","itemType":"Rod","rarity":"legendary","description":"This rod has a flanged head, and it functions as a magic mace that grants a +3 bonus to attack and damage rolls made with it. The rod has properties associated with six different buttons that are set in a row along the haft. It has three other properties as well, detailed below.\n\n**_Six Buttons_**. You can press one of the rod''s six buttons as a bonus action. A button''s effect lasts until you push a different button or until you push the same button again, which causes the rod to revert to its normal form.\n\nIf you press **button 1**, the rod becomes a _flame tongue_, as a fiery blade sprouts from the end opposite the rod''s flanged head.\n\nIf you press **button 2**, the rod''s flanged head folds down and two crescent-shaped blades spring out, transforming the rod into a magic battleaxe that grants a +3 bonus to attack and damage rolls made with it.\n\nIf you press **button 3**, the rod''s flanged head folds down, a spear point springs from the rod''s tip, and the rod''s handle lengthens into a 6-foot haft, transforming the rod into a magic spear that grants a +3 bonus to attack and damage rolls made with it.\n\nIf you press **button 4**, the rod transforms into a climbing pole up to 50 feet long, as you specify. In surfaces as hard as granite, a spike at the bottom and three hooks at the top anchor the pole. Horizontal bars 3 inches long fold out from the sides, 1 foot apart, forming a ladder. The pole can bear up to 4,000 pounds. More weight or lack of solid anchoring causes the rod to revert to its normal form.\n\nIf you press **button 5**, the rod transforms into a handheld battering ram and grants its user a +10 bonus to Strength checks made to break through doors, barricades, and other barriers.\n\nIf you press **button 6**, the rod assumes or remains in its normal form and indicates magnetic north. (Nothing happens if this function of the rod is used in a location that has no magnetic north.) The rod also gives you knowledge of your approximate depth beneath the ground or your height above it.\n\n**_Drain Life_**. When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Constitution saving throw. On a failure, the target takes an extra 4d6 necrotic damage, and you regain a number of hit points equal to half that necrotic damage. This property can''t be used again until the next dawn.\n\n**_Paralyze_**. When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Strength saving throw. On a failure, the target is paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on a success. This property can''t be used again until the next dawn.\n\n**_Terrify_**. While holding the rod, you can use an action to force each creature you can see within 30 feet of you to make a DC 17 Wisdom saving throw. On a failure, a target is frightened of you for 1 minute. A frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. This property can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Rod of Rulership', '/icons/items/_mono/R.svg', '{"name":"Rod of Rulership","itemType":"Rod","rarity":"rare","description":"You can use an action to present the rod and command obedience from each creature of your choice that you can see within 120 feet of you. Each target must succeed on a DC 15 Wisdom saving throw or be charmed by you for 8 hours. While charmed in this way, the creature regards you as its trusted leader. If harmed by you or your companions, or commanded to do something contrary to its nature, a target ceases to be charmed in this way. The rod can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Rod of Security', '/icons/items/_mono/R.svg', '{"name":"Rod of Security","itemType":"Rod","rarity":"very rare","description":"While holding this rod, you can use an action to activate it. The rod then instantly transports you and up to 199 other willing creatures you can see to a paradise that exists in an extraplanar space. You choose the form that the paradise takes. It could be a tranquil garden, lovely glade, cheery tavern, immense palace, tropical island, fantastic carnival, or whatever else you can imagine. Regardless of its nature, the paradise contains enough water and food to sustain its visitors. Everything else that can be interacted with inside the extraplanar space can exist only there. For example, a flower picked from a garden in the paradise disappears if it is taken outside the extraplanar space.\n\nFor each hour spent in the paradise, a visitor regains hit points as if it had spent 1 Hit Die. Also, creatures don''t age while in the paradise, although time passes normally. Visitors can remain in the paradise for up to 200 days divided by the number of creatures present (round down).\n\nWhen the time runs out or you use an action to end it, all visitors reappear in the location they occupied when you activated the rod, or an unoccupied space nearest that location. The rod can''t be used again until ten days have passed.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Rope of Climbing', '/icons/items/_mono/R.svg', '{"name":"Rope of Climbing","itemType":"Wondrous item","rarity":"uncommon","description":"This 60-foot length of silk rope weighs 3 pounds and can hold up to 3,000 pounds. If you hold one end of the rope and use an action to speak the command word, the rope animates. As a bonus action, you can command the other end to move toward a destination you choose. That end moves 10 feet on your turn when you first command it and 10 feet on each of your turns until reaching its destination, up to its maximum length away, or until you tell it to stop. You can also tell the rope to fasten itself securely to an object or to unfasten itself, to knot or unknot itself, or to coil itself for carrying.\n\nIf you tell the rope to knot, large knots appear at 1* foot intervals along the rope. While knotted, the rope shortens to a 50-foot length and grants advantage on checks made to climb it.\n\nThe rope has AC 20 and 20 hit points. It regains 1 hit point every 5 minutes as long as it has at least 1 hit point. If the rope drops to 0 hit points, it is destroyed.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Rope of Entanglement', '/icons/items/_mono/R.svg', '{"name":"Rope of Entanglement","itemType":"Wondrous item","rarity":"rare","description":"This rope is 30 feet long and weighs 3 pounds. If you hold one end of the rope and use an action to speak its command word, the other end darts forward to entangle a creature you can see within 20 feet of you. The target must succeed on a DC 15 Dexterity saving throw or become restrained.\n\nYou can release the creature by using a bonus action to speak a second command word. A target restrained by the rope can use an action to make a DC 15 Strength or Dexterity check (target''s choice). On a success, the creature is no longer restrained by the rope.\n\nThe rope has AC 20 and 20 hit points. It regains 1 hit point every 5 minutes as long as it has at least 1 hit point. If the rope drops to 0 hit points, it is destroyed.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Scarab of Protection', '/icons/items/_mono/S.svg', '{"name":"Scarab of Protection","itemType":"Wondrous item","rarity":"legendary","description":"If you hold this beetle-shaped medallion in your hand for 1 round, an inscription appears on its surface revealing its magical nature. It provides two benefits while it is on your person:\n\n* You have advantage on saving throws against spells.\n* The scarab has 12 charges. If you fail a saving throw against a necromancy spell or a harmful effect originating from an undead creature, you can use your reaction to expend 1 charge and turn the failed save into a successful one. The scarab crumbles into powder and is destroyed when its last charge is expended.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Scimitar of Speed', '/icons/items/_mono/S.svg', '{"name":"Scimitar of Speed","itemType":"Weapon","rarity":"very rare","description":"You gain a +2 bonus to attack and damage rolls made with this magic weapon. In addition, you can make one attack with it as a bonus action on each of your turns.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"scimitar","attunement":true}'),
    ('Shield of Missile Attraction', '/icons/items/_mono/S.svg', '{"name":"Shield of Missile Attraction","itemType":"Armor","rarity":"rare","description":"While holding this shield, you have resistance to damage from ranged weapon attacks.\n\n**_Curse_**. This shield is cursed. Attuning to it curses you until you are targeted by the _remove curse_ spell or similar magic. Removing the shield fails to end the curse on you. Whenever a ranged weapon attack is made against a target within 10 feet of you, the curse causes you to become the target instead.","source":"SRD 5.1, CC-BY-4.0","baseType":"shield","attunement":true}'),
    ('Slippers of Spider Climbing', '/icons/items/_mono/S.svg', '{"name":"Slippers of Spider Climbing","itemType":"Wondrous item","rarity":"uncommon","description":"While you wear these light shoes, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free. You have a climbing speed equal to your walking speed. However, the slippers don''t allow you to move this way on a slippery surface, such as one covered by ice or oil.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Sovereign Glue', '/icons/items/_mono/S.svg', '{"name":"Sovereign Glue","itemType":"Wondrous item","rarity":"legendary","description":"This viscous, milky-white substance can form a permanent adhesive bond between any two objects. It must be stored in a jar or flask that has been coated inside with _oil of slipperiness._ When found, a container contains 1d6 + 1 ounces.\n\nOne ounce of the glue can cover a 1-foot square surface. The glue takes 1 minute to set. Once it has done so, the bond it creates can be broken only by the application of _universal solvent_ or _oil of etherealness_, or with a _wish_ spell.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Spell Scroll', '/icons/items/_mono/S.svg', '{"name":"Spell Scroll","itemType":"Scroll","rarity":"rare","description":"A _spell scroll_ bears the words of a single spell, written in a mystical cipher. If the spell is on your class''s spell list, you can use an action to read the scroll and cast its spell without having to provide any of the spell''s components. Otherwise, the scroll is unintelligible.\n\nIf the spell is on your class''s spell list but of a higher level than you can normally cast, you must make an ability check using your spellcasting ability to determine whether you cast it successfully. The DC equals 10 + the spell''s level. On a failed check, the spell disappears from the scroll with no other effect. Once the spell is cast, the words on the scroll fade, and the scroll itself crumbles to dust.\n\nThe level of the spell on the scroll determines the spell''s saving throw DC and attack bonus, as well as the scroll''s rarity, as shown in the Spell Scroll table.\n\n**Spell Scroll (table)**\n\n| Spell Level | Rarity    | Save DC | Attack Bonus |\n|-------------|-----------|---------|--------------|\n| Cantrip     | Common    | 13      | +5           |\n| 1st         | Common    | 13      | +5           |\n| 2nd         | Uncommon  | 13      | +5           |\n| 3rd         | Uncommon  | 15      | +7           |\n| 4th         | Rare      | 15      | +7           |\n| 5th         | Rare      | 17      | +9           |\n| 6th         | Very rare | 17      | +9           |\n| 7th         | Very rare | 18      | +10          |\n| 8th         | Very rare | 18      | +10          |\n| 9th         | Legendary | 19      | +11          |\n\nA wizard spell on a _spell scroll_ can be copied just as spells in spellbooks can be copied. When a spell is copied from a the copier must succeed on an Intelligence (Arcana) check with a DC equal to 10 + the spell''s level. If the check succeeds, the spell is successfully copied. Whether the check succeeds or fails, the _spell scroll_ is destroyed.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Spellguard Shield', '/icons/items/_mono/S.svg', '{"name":"Spellguard Shield","itemType":"Armor","rarity":"very rare","description":"While holding this shield, you have advantage on saving throws against spells and other magical effects, and spell attacks have disadvantage against you.","source":"SRD 5.1, CC-BY-4.0","baseType":"shield","attunement":true}'),
    ('Sphere of Annihilation', '/icons/items/_mono/S.svg', '{"name":"Sphere of Annihilation","itemType":"Wondrous item","rarity":"legendary","description":"This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it.\n\nThe sphere obliterates all matter it passes through and all matter that passes through it. Artifacts are the exception. Unless an artifact is susceptible to damage from a _sphere of annihilation_, it passes through the sphere unscathed. Anything else that touches the sphere but isn''t wholly engulfed and obliterated by it takes 4d10 force damage.\n\nThe sphere is stationary until someone controls it. If you are within 60 feet of an uncontrolled sphere, you can use an action to make a DC 25 Intelligence (Arcana) check. On a success, the sphere levitates in one direction of your choice, up to a number of feet equal to 5 × your Intelligence modifier (minimum 5 feet). On a failure, the sphere moves 10 feet toward you. A creature whose space the sphere enters must succeed on a DC 13 Dexterity saving throw or be touched by it, taking 4d10 force damage.\n\nIf you attempt to control a sphere that is under another creature''s control, you make an Intelligence (Arcana) check contested by the other creature''s Intelligence (Arcana) check. The winner of the contest gains control of the sphere and can levitate it as normal.\n\nIf the sphere comes into contact with a planar portal, such as that created by the _gate_ spell, or an extradimensional space, such as that within a _portable hole_, the GM determines randomly what happens, using the following table.\n\n| d100   | Result                                                                                                                             |\n|--------|------------------------------------------------------------------------------------------------------------------------------------|\n| 01-50  | The sphere is destroyed.                                                                                                           |\n| 51-85  | The sphere moves through the portal or into the extradimensional space.                                                            |\n| 86-00  | A spatial rift sends each creature and object within 180 feet of the sphere, including the sphere, to a random plane of existence. |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Staff of Charming', '/icons/items/_mono/S.svg', '{"name":"Staff of Charming","itemType":"Staff","rarity":"rare","description":"While holding this staff, you can use an action to expend 1 of its 10 charges to cast _charm person_, _command_, _or comprehend languages_ from it using your spell save DC. The staff can also be used as a magic quarterstaff.\n\nIf you are holding the staff and fail a saving throw against an enchantment spell that targets only you, you can turn your failed save into a successful one. You can''t use this property of the staff again until the next dawn. If you succeed on a save against an enchantment spell that targets only you, with or without the staff''s intervention, you can use your reaction to expend 1 charge from the staff and turn the spell back on its caster as if you had cast the spell.\n\nThe staff regains 1d8 + 2 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff becomes a nonmagical quarterstaff.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a bard, cleric, druid, sorcerer, warlock, or wizard"}'),
    ('Staff of Fire', '/icons/items/_mono/S.svg', '{"name":"Staff of Fire","itemType":"Staff","rarity":"very rare","description":"You have resistance to fire damage while you hold this staff.\n\nThe staff has 10 charges. While holding it, you can use an action to expend 1 or more of its charges to cast one of the following spells from it, using your spell save DC: _burning hands_ (1 charge), _fireball_ (3 charges), or _wall of fire_ (4 charges).\n\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff blackens, crumbles into cinders, and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a druid, sorcerer, warlock, or wizard"}'),
    ('Staff of Frost', '/icons/items/_mono/S.svg', '{"name":"Staff of Frost","itemType":"Staff","rarity":"very rare","description":"You have resistance to cold damage while you hold this staff.\n\nThe staff has 10 charges. While holding it, you can use an action to expend 1 or more of its charges to cast one of the following spells from it, using your spell save DC: _cone of cold_ (5 charges), _fog cloud_ (1 charge), _ice storm_ (4 charges), or _wall of ice_ (4 charges).\n\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff turns to water and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a druid, sorcerer, warlock, or wizard"}'),
    ('Staff of Healing', '/icons/items/_mono/S.svg', '{"name":"Staff of Healing","itemType":"Staff","rarity":"rare","description":"This staff has 10 charges. While holding it, you can use an action to expend 1 or more of its charges to cast one of the following spells from it, using your spell save DC and spellcasting ability modifier: _cure wounds_ (1 charge per spell level, up to 4th), _lesser restoration_ (2 charges), or _mass cure wounds_ (5 charges).\n\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff vanishes in a flash of light, lost forever.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a bard, cleric, or druid"}'),
    ('Staff of Power', '/icons/items/_mono/S.svg', '{"name":"Staff of Power","itemType":"Staff","rarity":"very rare","description":"This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While holding it, you gain a +2 bonus to Armor Class, saving throws, and spell attack rolls.\n\nThe staff has 20 charges for the following properties. The staff regains 2d8 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff retains its +2 bonus to attack and damage rolls but loses all other properties. On a 20, the staff regains 1d8 + 2 charges.\n\n**_Power Strike_**. When you hit with a melee attack using the staff, you can expend 1 charge to deal an extra 1d6 force damage to the target.\n\n**_Spells_**. While holding this staff, you can use an action to expend 1 or more of its charges to cast one of the following spells from it, using your spell save DC and spell attack bonus: _cone of cold_ (5 charges), _fireball_ (5th-level version, 5 charges), _globe of invulnerability_ (6 charges), _hold monster_ (5 charges), _levitate_ (2 charges), _lightning bolt_ (5th-level version, 5 charges), _magic missile_ (1 charge), _ray of enfeeblement_ (1 charge), or _wall of force_ (5 charges).\n\n**_Retributive Strike_**. You can use an action to break the staff over your knee or against a solid surface, performing a retributive strike. The staff is destroyed and releases its remaining magic in an explosion that expands to fill a 30-foot-radius sphere centered on it.\n\nYou have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take force damage equal to 16 × the number of charges in the staff. Every other creature in the area must make a DC 17 Dexterity saving throw. On a failed save, a creature takes an amount of damage based on how far away it is from the point of origin, as shown in the following table. On a successful save, a creature takes half as much damage.\n\n| Distance from Origin  | Damage                                 |\n|-----------------------|----------------------------------------|\n| 10 ft. away or closer | 8 × the number of charges in the staff |\n| 11 to 20 ft. away     | 6 × the number of charges in the staff |\n| 21 to 30 ft. away     | 4 × the number of charges in the staff |","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a sorcerer, warlock, or wizard"}'),
    ('Staff of Striking', '/icons/items/_mono/S.svg', '{"name":"Staff of Striking","itemType":"Staff","rarity":"very rare","description":"This staff can be wielded as a magic quarterstaff that grants a +3 bonus to attack and damage rolls made with it.\n\nThe staff has 10 charges. When you hit with a melee attack using it, you can expend up to 3 of its charges. For each charge you expend, the target takes an extra 1d6 force damage. The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff becomes a nonmagical quarterstaff.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Staff of Swarming Insects', '/icons/items/_mono/S.svg', '{"name":"Staff of Swarming Insects","itemType":"Staff","rarity":"very rare","description":"This staff has 10 charges and regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, a swarm of insects consumes and destroys the staff, then disperses.\n\n**_Spells_**. While holding the staff, you can use an action to expend some of its charges to cast one of the following spells from it, using your spell save DC: _giant insect_ (4 charges) or _insect plague_ (5 charges).\n\n**_Insect Cloud_**. While holding the staff, you can use an action and expend 1 charge to cause a swarm of harmless flying insects to spread out in a 30-foot radius from you. The insects remain for 10 minutes, making the area heavily obscured for creatures other than you. The swarm moves with you, remaining centered on you. A wind of at least 10 miles per hour disperses the swarm and ends the effect.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a bard, cleric, druid, sorcerer, warlock, or wizard"}'),
    ('Staff of the Magi', '/icons/items/_mono/S.svg', '{"name":"Staff of the Magi","itemType":"Staff","rarity":"legendary","description":"This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls.\n\nThe staff has 50 charges for the following properties. It regains 4d6 + 2 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 20, the staff regains 1d12 + 1 charges.\n\n**_Spell Absorption_**. While holding the staff, you have advantage on saving throws against spells. In addition, you can use your reaction when another creature casts a spell that targets only you. If you do, the staff absorbs the magic of the spell, canceling its effect and gaining a number of charges equal to the absorbed spell''s level. However, if doing so brings the staff''s total number of charges above 50, the staff explodes as if you activated its retributive strike (see below).\n\n**_Spells_**. While holding the staff, you can use an action to expend some of its charges to cast one of the following spells from it, using your spell save DC and spellcasting ability: _conjure elemental_ (7 charges), _dispel magic_ (3 charges), _fireball_ (7th-level version, 7 charges), _flaming sphere_ (2 charges), _ice storm_ (4 charges), _invisibility_ (2 charges), _knock_ (2 charges), _lightning bolt_ (7th-level version, 7 charges), _passwall_ (5 charges), _plane shift_ (7 charges), _telekinesis_ (5 charges), _wall of fire_ (4 charges), or _web_ (2 charges).\n\nYou can also use an action to cast one of the following spells from the staff without using any charges: _arcane lock_, _detect magic_, _enlarge/reduce_, _light_, _mage hand_, or _protection from evil and good._\n\n**_Retributive Strike_**. You can use an action to break the staff over your knee or against a solid surface, performing a retributive strike. The staff is destroyed and releases its remaining magic in an explosion that expands to fill a 30-foot-radius sphere centered on it.\n\nYou have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take force damage equal to 16 × the number of charges in the staff. Every other creature in the area must make a DC 17 Dexterity saving throw. On a failed save, a creature takes an amount of damage based on how far away it is from the point of origin, as shown in the following table. On a successful save, a creature takes half as much damage.\n\n| Distance from Origin  | Damage                                 |\n|-----------------------|----------------------------------------|\n| 10 ft. away or closer | 8 × the number of charges in the staff |\n| 11 to 20 ft. away     | 6 × the number of charges in the staff |\n| 21 to 30 ft. away     | 4 × the number of charges in the staff |","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a sorcerer, warlock, or wizard"}'),
    ('Staff of the Python', '/icons/items/_mono/S.svg', '{"name":"Staff of the Python","itemType":"Staff","rarity":"very rare","description":"You can use an action to speak this staff''s command word and throw the staff on the ground within 10 feet of you. The staff becomes a giant constrictor snake under your control and acts on its own initiative count. By using a bonus action to speak the command word again, you return the staff to its normal form in a space formerly occupied by the snake.\n\nOn your turn, you can mentally command the snake if it is within 60 feet of you and you aren''t incapacitated. You decide what action the snake takes and where it moves during its next turn, or you can issue it a general command, such as to attack your enemies or guard a location.\n\nIf the snake is reduced to 0 hit points, it dies and reverts to its staff form. The staff then shatters and is destroyed. If the snake reverts to staff form before losing all its hit points, it regains all of them.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a cleric, druid, or warlock"}'),
    ('Staff of the Woodlands', '/icons/items/_mono/S.svg', '{"name":"Staff of the Woodlands","itemType":"Staff","rarity":"rare","description":"This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While holding it, you have a +2 bonus to spell attack rolls.\n\nThe staff has 10 charges for the following properties. It regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, the staff loses its properties and becomes a nonmagical quarterstaff.\n\n**_Spells_**. You can use an action to expend 1 or more of the staff''s charges to cast one of the following spells from it, using your spell save DC: _animal friendship_ (1 charge), _awaken_ (5 charges), _barkskin_ (2 charges), _locate animals or plants_ (2 charges), _speak with animals_ (1 charge), _speak with plants_ (3 charges), or _wall of thorns_ (6 charges).\n\nYou can also use an action to cast the _pass without trace_ spell from the staff without using any charges. **_Tree Form_**. You can use an action to plant one end of the staff in fertile earth and expend 1 charge to transform the staff into a healthy tree. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius.\n\nThe tree appears ordinary but radiates a faint aura of transmutation magic if targeted by _detect magic_. While touching the tree and using another action to speak its command word, you return the staff to its normal form. Any creature in the tree falls when it reverts to a staff.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a druid"}'),
    ('Staff of Thunder and Lightning', '/icons/items/_mono/S.svg', '{"name":"Staff of Thunder and Lightning","itemType":"Staff","rarity":"very rare","description":"This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. It also has the following additional properties. When one of these properties is used, it can''t be used again until the next dawn.\n\n**_Lightning_**. When you hit with a melee attack using the staff, you can cause the target to take an extra 2d6 lightning damage.\n\n**_Thunder_**. When you hit with a melee attack using the staff, you can cause the staff to emit a crack of thunder, audible out to 300 feet. The target you hit must succeed on a DC 17 Constitution saving throw or become stunned until the end of your next turn.\n\n**_Lightning Strike_**. You can use an action to cause a bolt of lightning to leap from the staff''s tip in a line that is 5 feet wide and 120 feet long. Each creature in that line must make a DC 17 Dexterity saving throw, taking 9d6 lightning damage on a failed save, or half as much damage on a successful one.\n\n**_Thunderclap_**. You can use an action to cause the staff to issue a deafening thunderclap, audible out to 600 feet. Each creature within 60 feet of you (not including you) must make a DC 17 Constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 1 minute. On a successful save, a creature takes half damage and isn''t deafened.\n\n**_Thunder and Lightning_**. You can use an action to use the Lightning Strike and Thunderclap properties at the same time. Doing so doesn''t expend the daily use of those properties, only the use of this one.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Staff of Withering', '/icons/items/_mono/S.svg', '{"name":"Staff of Withering","itemType":"Staff","rarity":"rare","description":"This staff has 3 charges and regains 1d3 expended charges daily at dawn.\n\nThe staff can be wielded as a magic quarterstaff. On a hit, it deals damage as a normal quarterstaff, and you can expend 1 charge to deal an extra 2d10 necrotic damage to the target. In addition, the target must succeed on a DC 15 Constitution saving throw or have disadvantage for 1 hour on any ability check or saving throw that uses Strength or Constitution.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a cleric, druid, or warlock"}'),
    ('Stone of Controlling Earth Elementals', '/icons/items/_mono/S.svg', '{"name":"Stone of Controlling Earth Elementals","itemType":"Wondrous item","rarity":"rare","description":"If the stone is touching the ground, you can use an action to speak its command word and summon an earth elemental, as if you had cast the _conjure elemental_ spell. The stone can''t be used this way again until the next dawn. The stone weighs 5 pounds.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Stone of Good Luck (Luckstone)', '/icons/items/_mono/S.svg', '{"name":"Stone of Good Luck (Luckstone)","itemType":"Wondrous item","rarity":"uncommon","description":"While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Sun Blade', '/icons/items/_mono/S.svg', '{"name":"Sun Blade","itemType":"Weapon","rarity":"rare","description":"This item appears to be a longsword hilt. While grasping the hilt, you can use a bonus action to cause a blade of pure radiance to spring into existence, or make the blade disappear. While the blade exists, this magic longsword has the finesse property. If you are proficient with shortswords or longswords, you are proficient with the _sun blade_.\n\nYou gain a +2 bonus to attack and damage rolls made with this weapon, which deals radiant damage instead of slashing damage. When you hit an undead with it, that target takes an extra 1d8 radiant damage.\n\nThe sword''s luminous blade emits bright light in a 15-foot radius and dim light for an additional 15 feet. The light is sunlight. While the blade persists, you can use an action to expand or reduce its radius of bright and dim light by 5 feet each, to a maximum of 30 feet each or a minimum of 10 feet each.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"longsword","attunement":true}'),
    ('Sword of Life Stealing', '/icons/items/_mono/S.svg', '{"name":"Sword of Life Stealing","itemType":"Weapon","rarity":"rare","description":"When you attack a creature with this magic weapon and roll a 20 on the attack roll, that target takes an extra 3d6 necrotic damage, provided that the target isn''t a construct or an undead. You gain temporary hit points equal to the extra damage dealt.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Sword of Sharpness', '/icons/items/_mono/S.svg', '{"name":"Sword of Sharpness","itemType":"Weapon","rarity":"very rare","description":"When you attack an object with this magic sword and hit, maximize your weapon damage dice against the target.\n\nWhen you attack a creature with this weapon and roll a 20 on the attack roll, that target takes an extra 4d6 slashing damage. Then roll another d20. If you roll a 20, you lop off one of the target''s limbs, with the effect of such loss determined by the GM. If the creature has no limb to sever, you lop off a portion of its body instead.\n\nIn addition, you can speak the sword''s command word to cause the blade to shed bright light in a 10* foot radius and dim light for an additional 10 feet. Speaking the command word again or sheathing the sword puts out the light.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword that deals slashing damage","attunement":true}'),
    ('Sword of Wounding', '/icons/items/_mono/S.svg', '{"name":"Sword of Wounding","itemType":"Weapon","rarity":"rare","description":"Hit points lost to this weapon''s damage can be regained only through a short or long rest, rather than by regeneration, magic, or any other means.\n\nOnce per turn, when you hit a creature with an attack using this magic weapon, you can wound the target. At the start of each of the wounded creature''s turns, it takes 1d4 necrotic damage for each time you''ve wounded it, and it can then make a DC 15 Constitution saving throw, ending the effect of all such wounds on itself on a success. Alternatively, the wounded creature, or a creature within 5 feet of it, can use an action to make a DC 15 Wisdom (Medicine) check, ending the effect of such wounds on it on a success.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Talisman of Pure Good', '/icons/items/_mono/T.svg', '{"name":"Talisman of Pure Good","itemType":"Wondrous item","rarity":"legendary","description":"This talisman is a mighty symbol of goodness. A creature that is neither good nor evil in alignment takes 6d6 radiant damage upon touching the talisman. An evil creature takes 8d6 radiant damage upon touching the talisman. Either sort of creature takes the damage again each time it ends its turn holding or carrying the talisman.\n\nIf you are a good cleric or paladin, you can use the talisman as a holy symbol, and you gain a +2 bonus to spell attack rolls while you wear or hold it.\n\nThe talisman has 7 charges. If you are wearing or holding it, you can use an action to expend 1 charge from it and choose one creature you can see on the ground within 120 feet of you. If the target is of evil alignment, a flaming fissure opens under it. The target must succeed on a DC 20 Dexterity saving throw or fall into the fissure and be destroyed, leaving no remains. The fissure then closes, leaving no trace of its existence. When you expend the last charge, the talisman disperses into motes of golden light and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a creature of good alignment"}'),
    ('Talisman of the Sphere', '/icons/items/_mono/T.svg', '{"name":"Talisman of the Sphere","itemType":"Wondrous item","rarity":"legendary","description":"When you make an Intelligence (Arcana) check to control a _sphere of annihilation_ while you are holding this talisman, you double your proficiency bonus on the check. In addition, when you start your turn with control over a _sphere of annihilation_, you can use an action to levitate it 10 feet plus a number of additional feet equal to 10 × your Intelligence modifier.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Talisman of Ultimate Evil', '/icons/items/_mono/T.svg', '{"name":"Talisman of Ultimate Evil","itemType":"Wondrous item","rarity":"legendary","description":"This item symbolizes unrepentant evil. A creature that is neither good nor evil in alignment takes 6d6 necrotic damage upon touching the talisman. A good creature takes 8d6 necrotic damage upon touching the talisman. Either sort of creature takes the damage again each time it ends its turn holding or carrying the talisman.\n\nIf you are an evil cleric or paladin, you can use the talisman as a holy symbol, and you gain a +2 bonus to spell attack rolls while you wear or hold it.\n\nThe talisman has 6 charges. If you are wearing or holding it, you can use an action to expend 1 charge from the talisman and choose one creature you can see on the ground within 120 feet of you. If the target is of good alignment, a flaming fissure opens under it. The target must succeed on a DC 20 Dexterity saving throw or fall into the fissure and be destroyed, leaving no remains. The fissure then closes, leaving no trace of its existence. When you expend the last charge, the talisman dissolves into foul-smelling slime and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a creature of evil alignment"}'),
    ('Tome of Clear Thought', '/icons/items/_mono/T.svg', '{"name":"Tome of Clear Thought","itemType":"Wondrous item","rarity":"very rare","description":"This book contains memory and logic exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Intelligence score increases by 2, as does your maximum for that score. The manual then loses its magic, but regains it in a century.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Tome of Leadership and Influence', '/icons/items/_mono/T.svg', '{"name":"Tome of Leadership and Influence","itemType":"Wondrous item","rarity":"very rare","description":"This book contains guidelines for influencing and charming others, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Charisma score increases by 2, as does your maximum for that score. The manual then loses its magic, but regains it in a century.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Tome of Understanding', '/icons/items/_mono/T.svg', '{"name":"Tome of Understanding","itemType":"Wondrous item","rarity":"very rare","description":"This book contains intuition and insight exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Wisdom score increases by 2, as does your maximum for that score. The manual then loses its magic, but regains it in a century.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Trident of Fish Command', '/icons/items/_mono/T.svg', '{"name":"Trident of Fish Command","itemType":"Weapon","rarity":"uncommon","description":"This trident is a magic weapon. It has 3 charges. While you carry it, you can use an action and expend 1 charge to cast _dominate beast_ (save DC 15) from it on a beast that has an innate swimming speed. The trident regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"trident","attunement":true}'),
    ('Universal Solvent', '/icons/items/_mono/U.svg', '{"name":"Universal Solvent","itemType":"Wondrous item","rarity":"legendary","description":"This tube holds milky liquid with a strong alcohol smell. You can use an action to pour the contents of the tube onto a surface within reach. The liquid instantly dissolves up to 1 square foot of adhesive it touches, including _sovereign glue._","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Vicious Weapon', '/icons/items/_mono/V.svg', '{"name":"Vicious Weapon","itemType":"Weapon","rarity":"rare","description":"When you roll a 20 on your attack roll with this magic weapon, your critical hit deals an extra 2d6 damage of the weapon''s type.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any"}'),
    ('Vorpal Sword', '/icons/items/_mono/V.svg', '{"name":"Vorpal Sword","itemType":"Weapon","rarity":"legendary","description":"You gain a +3 bonus to attack and damage rolls made with this magic weapon. In addition, the weapon ignores resistance to slashing damage.\n\nWhen you attack a creature that has at least one head with this weapon and roll a 20 on the attack roll, you cut off one of the creature''s heads. The creature dies if it can''t survive without the lost head. A creature is immune to this effect if it is immune to slashing damage, doesn''t have or need a head, has legendary actions, or the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 6d8 slashing damage from the hit.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword that deals slashing damage","attunement":true}'),
    ('Wand of Binding', '/icons/items/_mono/W.svg', '{"name":"Wand of Binding","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges for the following properties. It regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.\n\n**_Spells_**. While holding the wand, you can use an action to expend some of its charges to cast one of the following spells (save DC 17): _hold monster_ (5 charges) or _hold person_ (2 charges).\n\n**_Assisted Escape_**. While holding the wand, you can use your reaction to expend 1 charge and gain advantage on a saving throw you make to avoid being paralyzed or restrained, or you can expend 1 charge and gain advantage on any check you make to escape a grapple.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Enemy Detection', '/icons/items/_mono/W.svg', '{"name":"Wand of Enemy Detection","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges. While holding it, you can use an action and expend 1 charge to speak its command word. For the next minute, you know the direction of the nearest creature hostile to you within 60 feet, but not its distance from you. The wand can sense the presence of hostile creatures that are ethereal, invisible, disguised, or hidden, as well as those in plain sight. The effect ends if you stop holding the wand.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Wand of Fear', '/icons/items/_mono/W.svg', '{"name":"Wand of Fear","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges for the following properties. It regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.\n\n**_Command_**. While holding the wand, you can use an action to expend 1 charge and command another creature to flee or grovel, as with the _command_ spell (save DC 15).\n\n**_Cone of Fear_**. While holding the wand, you can use an action to expend 2 charges, causing the wand''s tip to emit a 60-foot cone of amber light. Each creature in the cone must succeed on a DC 15 Wisdom saving throw or become frightened of you for 1 minute. While it is frightened in this way, a creature must spend its turns trying to move as far away from you as it can, and it can''t willingly move to a space within 30 feet of you. It also can''t take reactions. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If it has nowhere it can move, the creature can use the Dodge action. At the end of each of its turns, a creature can repeat the saving throw, ending the effect on itself on a success.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Wand of Fireballs', '/icons/items/_mono/W.svg', '{"name":"Wand of Fireballs","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 or more of its charges to cast the _fireball_ spell (save DC 15) from it. For 1 charge, you cast the 3rd-level version of the spell. You can increase the spell slot level by one for each additional charge you expend.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Lightning Bolts', '/icons/items/_mono/W.svg', '{"name":"Wand of Lightning Bolts","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 or more of its charges to cast the _lightning bolt_ spell (save DC 15) from it. For 1 charge, you cast the 3rd-level version of the spell. You can increase the spell slot level by one for each additional charge you expend.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Magic Detection', '/icons/items/_mono/W.svg', '{"name":"Wand of Magic Detection","itemType":"Wand","rarity":"uncommon","description":"This wand has 3 charges. While holding it, you can expend 1 charge as an action to cast the _detect magic_ spell from it. The wand regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Wand of Magic Missiles', '/icons/items/_mono/W.svg', '{"name":"Wand of Magic Missiles","itemType":"Wand","rarity":"uncommon","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 or more of its charges to cast the _magic missile_ spell from it. For 1 charge, you cast the 1st-level version of the spell. You can increase the spell slot level by one for each additional charge you expend.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Wand of Paralysis', '/icons/items/_mono/W.svg', '{"name":"Wand of Paralysis","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges to cause a thin blue ray to streak from the tip toward a creature you can see within 60 feet of you. The target must succeed on a DC 15 Constitution saving throw or be paralyzed for 1 minute. At the end of each of the target''s turns, it can repeat the saving throw, ending the effect on itself on a success.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Polymorph', '/icons/items/_mono/W.svg', '{"name":"Wand of Polymorph","itemType":"Wand","rarity":"very rare","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges to cast the _polymorph_ spell (save DC 15) from it.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Secrets', '/icons/items/_mono/W.svg', '{"name":"Wand of Secrets","itemType":"Wand","rarity":"uncommon","description":"The wand has 3 charges. While holding it, you can use an action to expend 1 of its charges, and if a secret door or trap is within 30 feet of you, the wand pulses and points at the one nearest to you. The wand regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Wand of the War Mage, +1, +2, or +3', '/icons/items/_mono/W.svg', '{"name":"Wand of the War Mage, +1, +2, or +3","itemType":"Wand","rarity":"uncommon","description":"While holding this wand, you gain a bonus to spell attack rolls determined by the wand''s rarity. In addition, you ignore half cover when making a spell attack.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Web', '/icons/items/_mono/W.svg', '{"name":"Wand of Web","itemType":"Wand","rarity":"uncommon","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges to cast the _web_ spell (save DC 15) from it.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into ashes and is destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Wand of Wonder', '/icons/items/_mono/W.svg', '{"name":"Wand of Wonder","itemType":"Wand","rarity":"rare","description":"This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges and choose a target within 120 feet of you. The target can be a creature, an object, or a point in space. Roll d100 and consult the following table to discover what happens.\n\nIf the effect causes you to cast a spell from the wand, the spell''s save DC is 15. If the spell normally has a range expressed in feet, its range becomes 120 feet if it isn''t already.\n\nIf an effect covers an area, you must center the spell on and include the target. If an effect has multiple possible subjects, the GM randomly determines which ones are affected.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll a d20. On a 1, the wand crumbles into dust and is destroyed.\n\n| d100   | Effect                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   |\n|--------|----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n| 01-05  | You cast slow. 06-10 You cast faerie fire.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |\n| 11-15  | You are stunned until the start of your next turn, believing something awesome just happened. 16-20 You cast gust of wind.                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |\n| 21-25  | You cast detect thoughts on the target you chose. If you didn''t target a creature, you instead take 1d6 psychic damage.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  |\n| 26-30  | You cast stinking cloud.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |\n| 31-33  | Heavy rain falls in a 60-foot radius centered on the target. The area becomes lightly obscured. The rain falls until the start of your next turn.                                                                                                                                                                                                                                                                                                                                                                                                                                                        |\n| 34-36  | An animal appears in the unoccupied space nearest the target. The animal isn''t under your control and acts as it normally would. Roll a d100 to determine which animal appears. On a 01-25, a rhinoceros appears; on a 26-50, an elephant appears; and on a 51-100, a rat appears.                                                                                                                                                                                                                                                                                                                       |\n| 37-46  | You cast lightning bolt.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |\n| 47-49  | A cloud of 600 oversized butterflies fills a 30-foot radius centered on the target. The area becomes heavily obscured. The butterflies remain for 10 minutes.                                                                                                                                                                                                                                                                                                                                                                                                                                            |\n| 50-53  | You enlarge the target as if you had cast enlarge/reduce. If the target can''t be affected by that spell, or if you didn''t target a creature, you become the target.                                                                                                                                                                                                                                                                                                                                                                                                                                      |\n| 54-58  | You cast darkness.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |\n| 59-62  | Grass grows on the ground in a 60-foot radius centered on the target. If grass is already there, it grows to ten times its normal size and remains overgrown for 1 minute.                                                                                                                                                                                                                                                                                                                                                                                                                               |\n| 63-65  | An object of the GM''s choice disappears into the Ethereal Plane. The object must be neither worn nor carried, within 120 feet of the target, and no larger than 10 feet in any dimension.                                                                                                                                                                                                                                                                                                                                                                                                                |\n| 66-69  | You shrink yourself as if you had cast enlarge/reduce on yourself.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |\n| 70-79  | You cast fireball.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |\n| 80-84  | You cast invisibility on yourself.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |\n| 85-87  | Leaves grow from the target. If you chose a point in space as the target, leaves sprout from the creature nearest to that point. Unless they are picked off, the leaves turn brown and fall off after 24 hours.                                                                                                                                                                                                                                                                                                                                                                                          |\n| 88-90  | A stream of 1d4 × 10 gems, each worth 1 gp, shoots from the wand''s tip in a line 30 feet long and 5 feet wide. Each gem deals 1 bludgeoning damage, and the total damage of the gems is divided equally among all creatures in the line.                                                                                                                                                                                                                                                                                                                                                                 |\n| 91-95  | A burst of colorful shimmering light extends from you in a 30-foot radius. You and each creature in the area that can see must succeed on a DC 15 Constitution saving throw or become blinded for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.                                                                                                                                                                                                                                                                            |\n| 96-97  | The target''s skin turns bright blue for 1d10 days. If you chose a point in space, the creature nearest to that point is affected.                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |\n| 98-100 | If you targeted a creature, it must make a DC 15 Constitution saving throw. If you didn''t target a creature, you become the target and must make the saving throw. If the saving throw fails by 5 or more, the target is instantly petrified. On any other failed save, the target is restrained and begins to turn to stone. While restrained in this way, the target must repeat the saving throw at the end of its next turn, becoming petrified on a failure or ending the effect on a success. The petrification lasts until the target is freed by the greater restoration spell or similar magic. |","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a spellcaster"}'),
    ('Weapon, +1, +2, or +3', '/icons/items/_mono/W.svg', '{"name":"Weapon, +1, +2, or +3","itemType":"Weapon","rarity":"uncommon","description":"You have a bonus to attack and damage rolls made with this magic weapon. The bonus is determined by the weapon''s rarity.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any"}'),
    ('Well of Many Worlds', '/icons/items/_mono/W.svg', '{"name":"Well of Many Worlds","itemType":"Wondrous item","rarity":"legendary","description":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter.\n\nYou can use an action to unfold and place the _well of many worlds_ on a solid surface, whereupon it creates a two-way portal to another world or plane of existence. Each time the item opens a portal, the GM decides where it leads. You can use an action to close an open portal by taking hold of the edges of the cloth and folding it up. Once _well of many worlds_ has opened a portal, it can''t do so again for 1d8 hours.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Wind Fan', '/icons/items/_mono/W.svg', '{"name":"Wind Fan","itemType":"Wondrous item","rarity":"uncommon","description":"While holding this fan, you can use an action to cast the _gust of wind_ spell (save DC 13) from it. Once used, the fan shouldn''t be used again until the next dawn. Each time it is used again before then, it has a cumulative 20 percent chance of not working and tearing into useless, nonmagical tatters.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Winged Boots', '/icons/items/_mono/W.svg', '{"name":"Winged Boots","itemType":"Wondrous item","rarity":"uncommon","description":"While you wear these boots, you have a flying speed equal to your walking speed. You can use the boots to fly for up to 4 hours, all at once or in several shorter flights, each one using a minimum of 1 minute from the duration. If you are flying when the duration expires, you descend at a rate of 30 feet per round until you land.\n\nThe boots regain 2 hours of flying capability for every 12 hours they aren''t in use.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Wings of Flying', '/icons/items/_mono/W.svg', '{"name":"Wings of Flying","itemType":"Wondrous item","rarity":"rare","description":"While wearing this cloak, you can use an action to speak its command word. This turns the cloak into a pair of bat wings or bird wings on your back for 1 hour or until you repeat the command word as an action. The wings give you a flying speed of 60 feet. When they disappear, you can''t use them again for 1d12 hours.","source":"SRD 5.1, CC-BY-4.0","attunement":true}')
  ) as v(name, image_url, item)
  where not exists (
    select 1 from public.token_assets t
    where t.owner_id = me and t.token_type = 'item' and t.name = v.name
  );
end $$;
